import{_ as d,a0 as p,w as o,s as r,ao as l,I as a,x as t,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何改變你的終端顏色 | LCTT x X-CMD","titleTemplate":false,"description":"如何改變你的終端顏色 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何改變你的終端顏色 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何改變你的終端顏色 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190906 How to change the color of your Linux terminal","title":"如何改變你的終端顏色","tag":"201909","desc":""},"relativePath":"201909/20190906 How to change the color of your Linux terminal.md","filePath":"[post].md"}'),h={name:"201909/20190906 How to change the color of your Linux terminal.md"};function c(g,s,u,b,k,m){const i=p("Link");return o(),r("div",null,[s[31]||(s[31]=l('<h1 id="如何改變你的終端顏色" tabindex="-1">如何改變你的終端顏色 <a class="header-anchor" href="#如何改變你的終端顏色" aria-label="Permalink to “如何改變你的終端顏色”">​</a></h1><blockquote><p>使 Linux 變得豐富多彩（或單色）。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201909/10/111118bnvvcy6sntcs1s3t.jpg" alt=""></p><p>你可以使用特殊的 ANSI 編碼設置為 Linux 終端添加顏色，可以在終端命令或配置文件中動態添加，也可以在終端仿真器中使用現成的主題。無論哪種方式，你都可以黑色屏幕上找回懷舊的綠色或琥珀色文本。本文演示瞭如何使 Linux 變得豐富多彩（或單色）的方法。</p><h3 id="終端的功能特性" tabindex="-1">終端的功能特性 <a class="header-anchor" href="#終端的功能特性" aria-label="Permalink to “終端的功能特性”">​</a></h3><p>現代系統的終端的顏色配置通常默認至少是 xterm-256color，但如果你嘗試為終端添加顏色但未成功，則應檢查你的 <code>TERM</code> 設置。</p><p>從歷史上看，Unix 終端從字面上講是：用户可以輸入命令的共享計算機系統上實際的物理端點（終點）。它們專指通常用於遠程發出命令的電傳打字機（這也是我們今天在 Linux 中仍然使用 <code>/dev/tty</code> 設備的原因）。終端內置了 CRT 顯示器，因此用户可以坐在辦公室的終端上直接與大型機進行交互。CRT 顯示器價格昂貴 —— 無論是製造還是使用控制；比擔心抗鋸齒和現代計算機專家理所當然認為的漂亮信息，讓計算機吐出原始 ASCII 文本更容易。然而，即使在那時，技術的發展也很快，很快人們就會發現，隨着新的視頻顯示終端的設計，他們需要新的功能特性來提供可選功能。</p>',7)),a("p",null,[s[1]||(s[1]=t("例如，1978 年發佈的花哨的新 VT100 支持 ANSI 顏色，因此如果用户將終端類型識別為 vt100，則計算機可以提供彩色輸出，而基本串行設備可能沒有這樣的選項。同樣的原則適用於今天，它是由 ",-1)),s[2]||(s[2]=a("code",null,"TERM",-1)),s[3]||(s[3]=t()),n(i,{href:"https://opensource.com/article/19/8/what-are-environment-variables"},{default:e(()=>[...s[0]||(s[0]=[t("環境變量",-1)])]),_:1}),s[4]||(s[4]=t("設定的。你可以使用 ",-1)),s[5]||(s[5]=a("code",null,"echo",-1)),s[6]||(s[6]=t(" 檢查你的 ",-1)),s[7]||(s[7]=a("code",null,"TERM",-1)),s[8]||(s[8]=t(" 定義：",-1))]),s[32]||(s[32]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $TERM</span></span>
<span class="line"><span>xterm-256color</span></span></code></pre></div><p>過時的（但在一些系統上仍然為了向後兼容而維護）<code>/etc/termcap</code> 文件定義了終端和打印機的功能特性。現代的版本是 <code>terminfo</code>，位於 <code>/etc</code> 或 <code>/usr/share</code> 中，具體取決於你的發行版。 這些文件列出了不同類型終端中可用的功能特性，其中許多都是由歷史上的硬件定義的，如 vt100 到 vt220 的定義，以及 xterm 和 Xfce 等現代軟件仿真器。大多數軟件並不關心你使用的終端類型； 在極少數情況下，登錄到檢查兼容功能的服務器時，你可能會收到有關錯誤的終端類型的警告或錯誤。如果你的終端設置為功能特性很少的配置文件，但你知道你所使用的仿真器能夠支持更多功能特性，那麼你可以通過定義 <code>TERM</code> 環境變量來更改你的設置。你可以通過在 <code>~/.bashrc</code> 配置文件中導出 <code>TERM</code> 變量來完成此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export TERM=xterm-256color</span></span></code></pre></div><p>保存文件並重新載入設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><h3 id="ansi-顏色代碼" tabindex="-1">ANSI 顏色代碼 <a class="header-anchor" href="#ansi-顏色代碼" aria-label="Permalink to “ANSI 顏色代碼”">​</a></h3><p>現代終端繼承了用於“元”特徵的 ANSI 轉義序列。這些是特殊的字符序列，終端將其解釋為操作而不是字符。例如，此序列將清除屏幕，直到下一個提示符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ printf &#39;\\033[2J&#39;</span></span></code></pre></div><p>它不會清除你的歷史信息；它只是清除終端仿真器中的屏幕，因此它是一個安全且具有示範性的 ANSI 轉義序列。</p><p>ANSI 還具有設置終端顏色的序列。例如，鍵入此代碼會將後續文本更改為綠色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ printf &#39;\\033[32m&#39;</span></span></code></pre></div><p>只要你對相同的計算機使用同一個顏色，就可以使用顏色來幫助你記住你登錄的系統。例如，如果你經常通過 SSH 連接到服務器，則可以將服務器的提示符設置為綠色，以幫助你一目瞭然地將其與本地的提示符區分開來。 要設置綠色提示符，請在提示符前使用 ANSI 代碼設置為綠色，並使用代表正常默認顏色的代碼結束：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PS1=\`printf &quot;\\033[32m$ \\033[39m&quot;\`</span></span></code></pre></div><h3 id="前景色和背景色" tabindex="-1">前景色和背景色 <a class="header-anchor" href="#前景色和背景色" aria-label="Permalink to “前景色和背景色”">​</a></h3><p>你不僅可以設置文本的顏色。使用 ANSI 代碼，你還可以控制文本的背景顏色以及做一些基本的樣式。</p><p>例如，使用 <code>\\033[4m</code>，你可以為文本加上下劃線，或者使用 <code>\\033[5m</code> 你可以將其設置為閃爍的文本。起初這可能看起來很愚蠢，因為你可能不會將你的終端設置為所有文本帶有下劃線並整天閃爍， 但它對某些功能很有用。例如，你可以將 shell 腳本生成的緊急錯誤設置為閃爍（作為對用户的警報），或者你可以為 URL 添加下劃線。</p><p>作為參考，以下是前景色和背景色的代碼。前景色在 30 範圍內，而背景色在 40 範圍內：</p><div class="table-wrap"><table><thead><tr><th>顏色</th><th>前景色</th><th>背景色</th></tr></thead><tbody><tr><td>黑色</td><td>\\033[30m</td><td>\\033[40m</td></tr><tr><td>紅色</td><td>\\033[31m</td><td>\\033[41m</td></tr><tr><td>綠色</td><td>\\033[32m</td><td>\\033[42m</td></tr><tr><td>橙色</td><td>\\033[33m</td><td>\\033[43m</td></tr><tr><td>藍色</td><td>\\033[34m</td><td>\\033[44m</td></tr><tr><td>品紅</td><td>\\033[35m</td><td>\\033[45m</td></tr><tr><td>青色</td><td>\\033[36m</td><td>\\033[46m</td></tr><tr><td>淺灰</td><td>\\033[37m</td><td>\\033[47m</td></tr><tr><td>回退到發行版默認值</td><td>\\033[39m</td><td>\\033[49m</td></tr></tbody></table></div><p>還有一些可用於背景的其他顏色：</p><div class="table-wrap"><table><thead><tr><th>顏色</th><th>背景色</th></tr></thead><tbody><tr><td>深灰</td><td>\\033[100m</td></tr><tr><td>淺紅</td><td>\\033[101m</td></tr><tr><td>淺綠</td><td>\\033[102m</td></tr><tr><td>黃色</td><td>\\033[103m</td></tr><tr><td>淺藍</td><td>\\033[104m</td></tr><tr><td>淺紫</td><td>\\033[105m</td></tr><tr><td>藍綠</td><td>\\033[106m</td></tr><tr><td>白色</td><td>\\033[107m</td></tr></tbody></table></div><h3 id="持久設置" tabindex="-1">持久設置 <a class="header-anchor" href="#持久設置" aria-label="Permalink to “持久設置”">​</a></h3><p>在終端會話中設置顏色只是暫時的，相對無條件的。有時效果會持續幾行；這是因為這種設置顏色的方法依賴於 <code>printf</code> 語句來設置一種模式，該模式僅持續到其他設置覆蓋它。</p><p>終端仿真器通常獲取使用哪種顏色的指令的方式來自於 <code>LS_COLORS</code> 環境變量的設置，該設置又由 <code>dircolors</code> 的設置填充。你可以使用 <code>echo</code> 語句查看當前設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $LS_COLORS</span></span>
<span class="line"><span>rs=0:di=38;5;33:ln=38;5;51:mh=00:pi=40;</span></span>
<span class="line"><span>38;5;11:so=38;5;13:do=38;5;5:bd=48;5;</span></span>
<span class="line"><span>232;38;5;11:cd=48;5;232;38;5;3:or=48;</span></span>
<span class="line"><span>5;232;38;5;9:mi=01;05;37;41:su=48;5;</span></span>
<span class="line"><span>196;38;5;15:sg=48;5;11;38;5;16:ca=48;5;</span></span>
<span class="line"><span>196;38;5;226:tw=48;5;10;38;5;16:ow=48;5;</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>或者你可以直接使用 <code>dircolors</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dircolors --print-database</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span># image formats</span></span>
<span class="line"><span>.jpg 01;35</span></span>
<span class="line"><span>.jpeg 01;35</span></span>
<span class="line"><span>.mjpg 01;35</span></span>
<span class="line"><span>.mjpeg 01;35</span></span>
<span class="line"><span>.gif 01;35</span></span>
<span class="line"><span>.bmp 01;35</span></span>
<span class="line"><span>.pbm 01;35</span></span>
<span class="line"><span>.tif 01;35</span></span>
<span class="line"><span>.tiff 01;35</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>這看起來很神秘。文件類型後面的第一個數字是屬性代碼，它有六種選擇：</p><ul><li>00 無</li><li>01 粗體</li><li>04 下劃線</li><li>05 閃爍</li><li>07 反白</li><li>08 暗色</li></ul><p>下一個數字是簡化形式的顏色代碼。你可以通過獲取 ANSI 代碼的最後一個數字來獲取顏色代碼（綠色前景為 32，綠色背景為 42；紅色為 31 或 41，依此類推）。</p><p>你的發行版可能全局設置了 <code>LS_COLORS</code>，因此係統上的所有用户都會繼承相同的顏色。如果你想要一組自定義的顏色，可以使用 <code>dircolors</code>。首先，生成顏色設置的本地副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dircolors --print-database &gt; ~/.dircolors</span></span></code></pre></div>`,31)),a("p",null,[s[10]||(s[10]=t("根據需要編輯本地列表。如果你對自己的選擇感到滿意，請保存文件。你的顏色設置只是一個數據庫，不能由 ",-1)),n(i,{href:"https://opensource.com/article/19/7/master-ls-command"},{default:e(()=>[...s[9]||(s[9]=[t("ls",-1)])]),_:1}),s[11]||(s[11]=t(" 直接使用，但你可以使用 ",-1)),s[12]||(s[12]=a("code",null,"dircolors",-1)),s[13]||(s[13]=t(" 獲取可用於設置 ",-1)),s[14]||(s[14]=a("code",null,"LS_COLORS",-1)),s[15]||(s[15]=t(" 的 shellcode：",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dircolors --bourne-shell ~/.dircolors</span></span>
<span class="line"><span>LS_COLORS=&#39;rs=0:di=01;34:ln=01;36:mh=00:</span></span>
<span class="line"><span>pi=40;33:so=01;35:do=01;35:bd=40;33;01:</span></span>
<span class="line"><span>cd=40;33;01:or=40;31;01:mi=00:su=37;41:</span></span>
<span class="line"><span>sg=30;43:ca=30;41:tw=30;42:ow=34;</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>export LS_COLORS</span></span></code></pre></div><p>將輸出複製並粘貼到 <code>~/.bashrc</code> 文件中並重新加載。或者，你可以將該輸出直接轉儲到 <code>.bashrc</code> 文件中並重新加載。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dircolors --bourne-shell ~/.dircolors &amp;gt;&amp;gt; ~/.bashrc</span></span>
<span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>你也可以在啓動時使 Bash 解析 <code>.dircolors</code> 而不是手動進行轉換。實際上，你可能不會經常改變顏色，所以這可能過於激進，但如果你打算改變你的配色方案，這是一個選擇。在 <code>.bashrc</code> 文件中，添加以下規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[[ -e $HOME/.dircolors ]] &amp;&amp; eval &quot;\`dircolors --sh $HOME/.dircolors\`&quot;</span></span></code></pre></div><p>如果你的主目錄中有 <code>.dircolors</code> 文件，Bash 會在啓動時對其進行評估並相應地設置 <code>LS_COLORS</code>。</p><h3 id="顏色" tabindex="-1">顏色 <a class="header-anchor" href="#顏色" aria-label="Permalink to “顏色”">​</a></h3><p>在終端中使用顏色是一種可以為你自己提供特定信息的快速視覺參考的簡單方法。但是，你可能不希望過於依賴它們。畢竟，顏色不是通用的，所以如果其他人使用你的系統，他們可能不會像你那樣看懂顏色代表的含義。此外，如果你使用各種工具與計算機進行交互，你可能還會發現某些終端或遠程連接無法提供你期望的顏色（或根本不提供顏色）。</p><p>除了上述警示之外，顏色在某些工作流程中可能很有用且很有趣，因此創建一個 <code>.dircolor</code> 資料庫並根據你的想法對其進行自定義吧。</p><hr>`,10)),a("p",null,[s[17]||(s[17]=t("via: ",-1)),n(i,{href:"https://opensource.com/article/19/9/linux-terminal-colors"},{default:e(()=>[...s[16]||(s[16]=[t("https://opensource.com/article/19/9/linux-terminal-colors",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=t("作者：",-1)),n(i,{href:"https://opensource.com/users/seth"},{default:e(()=>[...s[18]||(s[18]=[t("Seth Kenlon",-1)])]),_:1}),s[23]||(s[23]=t(" 選題：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[19]||(s[19]=[t("lujun9972",-1)])]),_:1}),s[24]||(s[24]=t(" 譯者：",-1)),n(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[20]||(s[20]=[t("wxy",-1)])]),_:1}),s[25]||(s[25]=t(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[21]||(s[21]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=t("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[26]||(s[26]=[t("LCTT",-1)])]),_:1}),s[29]||(s[29]=t(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:e(()=>[...s[27]||(s[27]=[t("Linux中國",-1)])]),_:1}),s[30]||(s[30]=t(" 榮譽推出",-1))])])}const y=d(h,[["render",c]]);export{x as __pageData,y as default};
